import { describe, expect, it } from 'vitest'
import gtJson from '../../../../benchmarks/gatsu/gt_spec.json'
import type { Spec } from '../../types/spec'
import fixture from './parity.fixture.json'
import { applyOps, type EditorOp } from './reducer'

// Generated by tests/test_editor_parity.py from core.spec.ops.apply (UPDATE_PARITY=1 to refresh).
const gt = gtJson as unknown as Spec

function strip<T extends object>(items: T[] | undefined, drop: string[] = ['provenance']): object[] {
  return (items ?? []).map((it) => Object.fromEntries(Object.entries(it).filter(([k]) => !drop.includes(k))))
}

describe('client reducer matches core.spec.ops.apply', () => {
  for (const c of fixture.cases) {
    it(c.name, () => {
      const r = applyOps(gt, c.ops as EditorOp[])
      expect(r.failed).toEqual([])
      expect(strip(r.spec.walls)).toEqual(c.expected.walls)
      expect(strip(r.spec.openings)).toEqual(c.expected.openings)
      expect(strip(r.spec.stairs, ['provenance', 'room_id'])).toEqual(c.expected.stairs)
      expect(strip(r.spec.objects)).toEqual(c.expected.objects)
      expect(r.spec.meta.defaults).toEqual(c.expected.defaults)
      expect(r.spec.meta.id_seq).toEqual(c.expected.id_seq)
    })
  }
})
